INSERT INTO agent_draft_assist_run(id,tenant_id,application_id,application_version,status,version,context_json,state_json,created_at,trace_id)
SELECT #{id},tenant_id,id,version,'QUEUED',1,#{stateJson},#{stateJson2},#{createdAt},#{traceId} FROM approval_application
WHERE tenant_id=#{tenantId} AND id=#{applicationId} AND version=#{applicationVersion} AND created_by=#{requestedBy}
